mapper.select:
SELECT chapter_id, title, description, course_id, created_at, updated_at
FROM edu.chapters
WHERE chapter_id = #{chapterId}
  AND course_id = #{courseId}

mapper.delete:
DELETE FROM edu.chapters
WHERE chapter_id = #{chapterId}
  AND course_id = #{courseId}

mapper.update:
UPDATE edu.chapters
SET title = #{title},
    description = #{description},
    updated_at = NOW()
WHERE chapter_id = #{chapterId}
  AND course_id = #{courseId}

mapper.select:
SELECT learning_outcome_id
FROM edu.chapter_learning_outcomes
WHERE chapter_id = #{chapterId}

mapper.delete:
DELETE FROM edu.chapter_learning_outcomes
WHERE chapter_id = #{chapterId}
  AND learning_outcome_id = #{learningOutcomeId}
